from __future__ import annotationsfrom abc import ABC, abstractmethodfrom dataclasses import asdict, dataclassfrom pathlib import Pathimport sysfrom typing import Any, Callable, Dict, Optional, Tuple, Unionimport loggingimport cv2import numpy as npimport torchfrom scipy.spatial import cKDTreefrom sklearn.cluster import MiniBatchKMeansfrom sklearn.neighbors import NearestNeighborsfrom torch_geometric.data import HeteroDatafrom tqdm import tqdmproject_root = Path(__file__).resolve().parent.parent.parentif str(project_root) not in sys.path:    sys.path.append(str(project_root))from src.graph_creation_new.config import BuildContextclass GraphBuildPipeline(ABC):    @property    @abstractmethod    def name(self) -> str:        pass    @abstractmethod    def build(self, context: BuildContext) -> HeteroData:        passclass StepPipeline(GraphBuildPipeline):    @property    @abstractmethod    def steps(self) -> Tuple[Callable[[BuildContext], None], ...]:        pass    @abstractmethod    def finalize(self, context: BuildContext) -> HeteroData:        pass    def build(self, context: BuildContext) -> HeteroData:        slide_name = Path(context.slide_path).name        with tqdm(self.steps, total=len(self.steps), desc=f"slide:{slide_name}", unit="step", leave=False) as step_bar:            for step in step_bar:                step_name = step.__name__.replace("_step", "").strip("_")                step_bar.set_postfix_str(step_name)                step(context)        return self.finalize(context)